package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class GroupMySubmissionsIntegrationTest {
 SubmissionGradeStoreIntegrationTest f;GroupMySubmissionsStore store;GradeRetractionStore markers;
 @BeforeEach void setup(){f=new SubmissionGradeStoreIntegrationTest();f.setup();store=new GroupMySubmissionsStore(f.f.f.source,new GroupStore(f.f.f.source,Clock.systemUTC()));markers=new GradeRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 GroupMySubmissionsStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,f.f.author,after,limit,filter);}
 GroupMySubmissionsStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 GradeRetractionStore.Retraction mark(long target,long expected,String state){return markers.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new GradeRetractionInput(state,"PRIVATE annotation reason"),f.f.f.trace);}
 @Test void zeroScoreCountsAsCurrentAndResubmissionMakesOnlyOldAnswerGradeOutdated(){var grade=f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE zero-grade reason",1,2),f.f.f.trace);assertEquals(0,grade.score());assertEquals("CURRENT",row().gradingStatus());assertTrue(list("NEEDS_GRADING",null,20).items().isEmpty());assertEquals(1,list("CURRENT",null,20).items().size());f.f.submit(f.f.f.key(),1,2,"NEW PRIVATE ANSWER");assertEquals("OUTDATED",row().gradingStatus());assertEquals(2,row().version());assertEquals(1L,row().gradedSubmissionVersion());assertEquals(1,list("OUTDATED",null,20).items().size());assertTrue(list("CURRENT",null,20).items().isEmpty());f.change(1,2,"PRIVATE new-answer grade");assertEquals("CURRENT",row().gradingStatus());assertEquals(2L,row().gradeVersion());assertEquals(2L,row().gradedSubmissionVersion());}
 @Test void onlyLatestGradeVersionMarkerAffectsCurrentAnswerStatus(){f.change(0,1,"First grade");mark(1,0,"RETRACTED");assertEquals("RETRACTED",row().gradingStatus());assertEquals(1,list("RETRACTED",null,20).items().size());mark(1,1,"RESTORED");assertEquals("CURRENT",row().gradingStatus());assertEquals("RESTORED",row().gradeRetractionState());f.change(1,1,"New independently reviewed grade");mark(1,2,"RETRACTED");assertEquals("CURRENT",row().gradingStatus());assertEquals("NONE",row().gradeRetractionState());assertNull(row().retractionVersion());assertTrue(list("RETRACTED",null,20).items().isEmpty());mark(2,0,"RETRACTED");assertEquals("RETRACTED",row().gradingStatus());assertEquals(1L,row().retractionVersion());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());mark(2,1,"RESTORED");assertEquals("CURRENT",row().gradingStatus());assertEquals(2L,row().retractionVersion());}
 @Test void withdrawnOldAnswerStaysOutdatedAndHistoricalMarkerCannotInvalidateNewGrade(){f.change(0,1,"First");f.f.submit(f.f.f.key(),1,2,"Second answer");mark(1,0,"RETRACTED");assertEquals("OUTDATED",row().gradingStatus());assertEquals("RETRACTED",row().gradeRetractionState());assertTrue(list("RETRACTED",null,20).items().isEmpty());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());f.change(1,2,"Second grade");assertEquals("CURRENT",row().gradingStatus());assertEquals("NONE",row().gradeRetractionState());}
 @Test void unknownOrMissingMarkerStateIsNeverReportedAsCurrent(){f.change(0,1,"Grade");var marker=mark(1,0,"RETRACTED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM grade_retraction WHERE retraction_id=?",String.class,marker.retractionId());try{for(String expression:List.of("jsonb_set(snapshot,'{state}','\"INVALID\"')","snapshot-'state'")){f.f.f.jdbc.update("UPDATE grade_retraction SET snapshot="+expression+" WHERE retraction_id=?",marker.retractionId());assertEquals("UNAVAILABLE",row().gradingStatus());assertEquals("UNKNOWN",row().gradeRetractionState());assertTrue(list("CURRENT",null,20).items().isEmpty());assertEquals(1,list("UNAVAILABLE",null,20).items().size());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());}}finally{f.f.f.jdbc.update("UPDATE grade_retraction SET snapshot=?::jsonb WHERE retraction_id=?",saved,marker.retractionId());}}
 @Test void closedArchivedReadsPreserveOriginalGradeFeedbackAndAudit(){var grade=f.change(0,1,"Grade");var marker=mark(1,0,"RETRACTED");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int count=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(var filter:GroupMySubmissionsStore.FILTERS)list(filter,null,20);assertEquals("RETRACTED",row().gradingStatus());assertEquals(grade,f.get(f.f.author,false).grade());assertEquals(marker,markers.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction());assertEquals(count,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));}
 @Test void concurrentNewAnswerAndGradeAreReadAsOneStatementSnapshot()throws Exception{f.change(0,1,"First");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reads=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertTrue(v.gradedSubmissionVersion()<=v.version());if(v.gradingStatus().equals("CURRENT"))assertEquals(v.version(),v.gradedSubmissionVersion());else assertEquals("OUTDATED",v.gradingStatus());}return true;});var writes=pool.submit(()->{barrier.await();f.f.submit(f.f.f.key(),1,2,"New answer");return f.change(1,2,"New grade");});assertTrue(reads.get(20,TimeUnit.SECONDS));assertEquals(2,writes.get(20,TimeUnit.SECONDS).version());assertEquals("CURRENT",row().gradingStatus());}}

 @Test void rubricComputedZeroAndDirectModeUseTheSameQueueAndExactMarker(){var g=new RubricGradingStoreIntegrationTest();g.setup();var q=new GroupMySubmissionsStore(g.f.f.f.source,new GroupStore(g.f.f.f.source,Clock.systemUTC()));var zero=g.change(0,g.input(0,0,"PRIVATE rubric zero"));assertEquals(0,zero.grade().score());var row=q.list(g.f.f.group,g.f.f.space,g.author,null,20,"CURRENT").items().getFirst();assertEquals("CURRENT",row.gradingStatus());assertEquals(1L,row.gradeVersion());var markers=new GradeRetractionStore(g.f.f.f.source,g.f.f.store,g.submissions,Clock.systemUTC());markers.change(g.f.f.group,g.f.f.space,g.f.f.study,g.f.assignment,g.answer.submissionId(),g.f.f.f.owner,1,0,new GradeRetractionInput("RETRACTED","PRIVATE reason"),g.f.f.f.trace);assertEquals(1,q.list(g.f.f.group,g.f.f.space,g.author,null,20,"NEEDS_GRADING").items().size());g.change(1,g.direct(0,"PRIVATE direct zero",1,2));var next=q.list(g.f.f.group,g.f.f.space,g.author,null,20,"CURRENT").items().getFirst();assertEquals(2L,next.gradeVersion());assertEquals("NONE",next.gradeRetractionState());}

 @Test void onlyFreshActorOwnWorkIsReturnedAcrossAssignmentsIncludingOwner(){
  var other=f.f.f.ids.next();f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,other,0,2,f.f.f.key(),"OTHER PRIVATE ANSWER",f.f.f.trace);
  var own=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,0,2,f.f.f.key(),"OWNER PRIVATE ANSWER",f.f.f.trace).submission();
  UUID task=f.f.parent.create(f.f.f.key()).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,f.f.study,task,f.f.f.owner,1,"OPEN",f.f.f.trace);f.f.store.submit(f.f.group,f.f.space,f.f.study,task,f.f.author,0,2,f.f.f.key(),"MY SECOND ASSIGNMENT",f.f.f.trace);
  assertEquals(2,list("ALL",null,100).items().size());assertEquals(1,store.list(f.f.group,f.f.space,other,null,100,"ALL").items().size());assertEquals(own.submissionId(),store.list(f.f.group,f.f.space,f.f.f.owner,null,100,"ALL").items().getFirst().submissionId());assertTrue(store.list(f.f.group,f.f.space,f.f.f.ids.next(),null,100,"ALL").items().isEmpty());
  var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(15,json.size());for(String key:List.of("authorId","score","reason","content","graderId","snapshot","description"))assertFalse(json.has(key));assertEquals(f.f.assignment,row().assignmentId());assertEquals("OPEN",row().assignmentState());assertNotNull(row().assignmentTitle());
 }
 @Test void groupSpacePendingEmptyAndQueryBoundsFailClosed(){
  f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),f.f.author,null,20,"ALL"));var groups=new GroupStore(f.f.f.source,Clock.systemUTC());var pending=groups.request(f.f.f.owner,f.f.f.key(),"Pending private Group","",f.f.f.trace);var space=f.f.f.ids.next();f.status(404,()->store.list(pending.groupId(),space,f.f.author,null,20,"ALL"));groups.activate(pending.groupId(),f.f.f.owner,space,f.f.f.trace);assertTrue(store.list(pending.groupId(),space,f.f.author,null,20,"ALL").items().isEmpty());for(int n:List.of(0,101))f.status(400,()->list("ALL",null,n));for(String filter:List.of("all","HAS_FEEDBACK","","CURRENT' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void filteringPrecedesKeysetLimitAcrossManyOwnAssignments(){
  for(int n=0;n<12;n++){UUID task=f.f.parent.create(f.f.f.key()).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,f.f.study,task,f.f.f.owner,1,"OPEN",f.f.f.trace);var answer=f.f.store.submit(f.f.group,f.f.space,f.f.study,task,f.f.author,0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();if(n%2==0)f.store.change(f.f.group,f.f.space,f.f.study,task,answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE reason",1,2),f.f.f.trace);}
  assertEquals(13,list("ALL",null,100).items().size());assertEquals(6,list("CURRENT",null,100).items().size());assertEquals(7,list("MISSING",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,2);seen.addAll(p.items().stream().map(GroupMySubmissionsStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(GroupMySubmissionsStore.Row::submissionId).toList(),seen);assertEquals(6,new HashSet<>(seen).size());
 }


 UUID task(UUID study){var a=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Shared task","Instructions",f.f.f.trace).assignment();f.f.parent.store.state(f.f.group,f.f.space,study,a.assignmentId(),f.f.f.owner,1,"OPEN",f.f.f.trace);return a.assignmentId();}
 @Test void allStudiesKeepOwnScopeCurrentLabelsOriginalInstructionsAndNoCourseEvents(){
  var b=f.f.parent.parent.create(f.f.f.key()).study();var id=task(b.studyId());var own=f.f.store.submit(f.f.group,f.f.space,b.studyId(),id,f.f.author,0,2,f.f.f.key(),"MY B PRIVATE",f.f.f.trace).submission();f.f.store.submit(f.f.group,f.f.space,b.studyId(),id,f.f.f.owner,0,2,f.f.f.key(),"OWNER B SECRET",f.f.f.trace);f.f.store.submit(f.f.group,f.f.space,b.studyId(),id,f.f.f.ids.next(),0,2,f.f.f.key(),"PEER B SECRET",f.f.f.trace);task(b.studyId());f.f.parent.parent.store.metadata(f.f.group,f.f.space,b.studyId(),f.f.f.owner,1,"Current B <script>","Current",f.f.f.trace);f.f.parent.store.metadata(f.f.group,f.f.space,b.studyId(),id,f.f.f.owner,2,"Current task","New instructions",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,b.studyId(),f.f.f.owner,2,"RETIRED",f.f.f.trace);
  assertEquals(2,list("ALL",null,100).items().size());var v=list("ALL",null,100).items().stream().filter(x->x.submissionId().equals(own.submissionId())).findFirst().orElseThrow();assertEquals(b.studyId(),v.studyId());assertEquals("Current B <script>",v.studyTitle());assertEquals("RETIRED",v.studyState());assertEquals("Current task",v.assignmentTitle());assertEquals(2,v.assignmentVersion());assertEquals("MISSING",v.gradingStatus());int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMySubmissionsStore.FILTERS)list(filter,null,100);assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM group_course WHERE group_id=?",Integer.class,f.f.group));
 }
 @Test void filteredKeysetCrossesStudiesAndExcludesOtherAuthors(){
  var b=f.f.parent.parent.create(f.f.f.key()).study();for(int n=0;n<12;n++){UUID st=n%2==0?f.f.study:b.studyId(),id=task(st);var answer=f.f.store.submit(f.f.group,f.f.space,st,id,f.f.author,0,2,f.f.f.key(),"OWN",f.f.f.trace).submission();f.f.store.submit(f.f.group,f.f.space,st,id,f.f.f.ids.next(),0,2,f.f.f.key(),"FOREIGN",f.f.f.trace);if(n%3==0)f.store.change(f.f.group,f.f.space,st,id,answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE",1,2),f.f.f.trace);}
  assertEquals(13,list("ALL",null,100).items().size());assertEquals(4,list("CURRENT",null,100).items().size());assertEquals(9,list("MISSING",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,1);seen.addAll(p.items().stream().map(GroupMySubmissionsStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(GroupMySubmissionsStore.Row::submissionId).toList(),seen);assertEquals(4,new HashSet<>(seen).size());
 }
 @Test void anotherGroupAndSpaceCannotLeakSameActorWork(){
  var other=new SubmissionGradeStoreIntegrationTest();other.setup();other.f.store.submit(other.f.group,other.f.space,other.f.study,other.f.assignment,f.f.author,0,2,other.f.f.key(),"OTHER GROUP PRIVATE",other.f.f.trace);assertEquals(1,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().noneMatch(v->v.studyId().equals(other.f.study)));f.status(404,()->store.list(f.f.group,other.f.space,f.f.author,null,20,"ALL"));f.status(404,()->store.list(other.f.group,f.f.space,f.f.author,null,20,"ALL"));
 }
}
